  updateStats: (stats: StatsData) => void;
}

// 毎秒の stats 更新による App 全体の不要な再レンダリングを防ぐため分離した HUDStats コンポーネント
const HUDStats = memo(
  forwardRef<HUDStatsHandle>((_, ref) => {
    const [stats, setStats] = useState<StatsData>({ fps: 60, activeParticles: 450 });

    useImperativeHandle(ref, () => ({
      updateStats: (newStats: StatsData) => {
        setStats(newStats);
      },
    }));

    return (
      <div className="hud-stats">
        <div className="hud-stat-item" title="フレームレート">
          <span>FPS:</span>
          <strong
            style={{
              color: stats.fps >= 50 ? '#00f2fe' : stats.fps >= 30 ? '#ffaa00' : '#ff007f',
            }}
          >
            {stats.fps}
          </strong>
        </div>
        <div className="hud-stat-item" title="画面上に存在するパーティクル総数">
          <span>粒子数:</span>
          <strong>{stats.activeParticles}</strong>
        </div>
      </div>
    );
  })
);

